const dialog=document.querySelector("#project-dialog");
const dialogContent=document.querySelector("#dialog-content");
const selector=document.querySelector("#language");
let language;
try { language=localStorage.getItem("portfolio-language"); } catch (_) {}
if (!LANGUAGES.includes(language)) {
  const browserLanguage=(navigator.language||"en").split("-")[0].toLowerCase();
  language=LANGUAGES.includes(browserLanguage)?browserLanguage:"en";
}
const esc=value=>String(value).replace(/[&<>"']/g,char=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[char]));
const projectUrl=project=>"https://github.com/artyom129/"+encodeURIComponent(project.repo);
function activeProject(){
  const slug=new URL(location.href).searchParams.get("project");
  return PROJECTS.find(project=>project.slug===slug);
}
function renderCards(){
  const t=UI[language],stories=PROJECT_COPY[language];
  grid.innerHTML=PROJECTS.map((project,index)=>{
    const story=stories[index];
    return '<article class="project-card"><div class="project-card-top"><span class="project-index">'+String(index+1).padStart(2,"0")+' / 06</span><span class="project-category">'+esc(t.cats[index])+'</span></div><h3>'+esc(project.name)+'</h3><p class="project-summary">'+esc(story[0])+'</p><div class="project-tags">'+project.tags.map(tag=>'<span>'+esc(tag)+'</span>').join("")+'</div><div class="project-card-bottom"><button type="button" class="project-open" data-project="'+esc(project.slug)+'" aria-label="'+esc(t.viewProject+": "+project.name)+'">'+esc(t.viewProject)+' <span aria-hidden="true">↗</span></button><a class="project-repo" href="'+esc(projectUrl(project))+'" target="_blank" rel="noopener noreferrer">'+esc(t.viewRepo)+' ↗</a></div></article>';
  }).join("");
}
function section(label,body){
  return '<section class="dialog-section"><h3 class="dialog-section-label">'+esc(label)+'</h3><div class="dialog-section-content">'+body+'</div></section>';
}
function renderDialog(project){
  if(!project)return;
  const index=PROJECTS.indexOf(project),t=UI[language],story=PROJECT_COPY[language][index];
  dialogContent.innerHTML='<p class="dialog-kicker">'+esc(String(index+1).padStart(2,"0")+' / 06 — '+t.cats[index])+'</p>'+
    '<h2 class="dialog-title" id="dialog-title">'+esc(project.name)+'</h2>'+
    '<p class="dialog-lead">'+esc(story[0])+'</p>'+
    '<div class="dialog-links"><a class="button button-primary" href="'+esc(projectUrl(project))+'" target="_blank" rel="noopener noreferrer">'+esc(t.source)+' <span aria-hidden="true">↗</span></a></div>'+
    '<div class="dialog-meta"><div class="meta-row"><span>'+esc(t.role)+'</span><strong>'+esc(t.independent)+'</strong></div><div class="meta-row"><span>'+esc(t.scope)+'</span><strong>'+esc(t.focus[index])+'</strong></div><div class="meta-row"><span>'+esc(t.stack)+'</span><strong>'+esc(project.tags.join(" · "))+'</strong></div></div>'+
    section(t.problem,'<p>'+esc(story[1])+'</p>')+
    section(t.solution,'<p>'+esc(story[2])+'</p>')+
    section(t.highlights,'<ul>'+story.slice(3).map(item=>'<li>'+esc(item)+'</li>').join("")+'</ul>')+
    section(t.architecture,'<div class="architecture">'+PROJECT_FLOWS[language][index].map((item,i)=>(i?'<b aria-hidden="true">'+(language==='ar'?'←':'→')+'</b>':"")+'<span>'+esc(item)+'</span>').join("")+'</div>')+
    '<p class="dialog-bottom">'+esc(t.openSource)+'</p>';
}
function syncDialog(){
  const project=activeProject();
  if(project){
    renderDialog(project);
    if(!dialog.open)dialog.showModal();
  } else if(dialog.open) dialog.close();
}
function setLanguage(next){
  if(!LANGUAGES.includes(next))return;
  language=next;
  document.documentElement.lang=next;
  document.documentElement.dir=next==="ar"?"rtl":"ltr";
  selector.value=next;
  document.querySelectorAll("[data-i18n]").forEach(node=>{
    const key=node.dataset.i18n,content=UI[next][key];
    if(content===undefined)return;
    if(key==="contactHeading")node.innerHTML=content;
    else node.textContent=content;
  });
  document.querySelector(".dialog-close").setAttribute("aria-label",UI[next].close);
  document.title="Artyom Koncha — "+UI[next].navProjects;
  renderCards();
  if(activeProject())renderDialog(activeProject());
  try { localStorage.setItem("portfolio-language",next); } catch (_) {}
}
grid.addEventListener("click",event=>{
  const button=event.target.closest("[data-project]");
  if(!button)return;
  const url=new URL(location.href);
  url.searchParams.set("project",button.dataset.project);
  history.pushState({project:button.dataset.project},"",url);
  syncDialog();
});
document.querySelector("#dialog-close").addEventListener("click",()=>dialog.close());
dialog.addEventListener("click",event=>{if(event.target===dialog)dialog.close();});
dialog.addEventListener("close",()=>{
  if(activeProject()){
    const url=new URL(location.href);
    url.searchParams.delete("project");
    history.replaceState({},"",url);
  }
});
selector.addEventListener("change",()=>setLanguage(selector.value));
window.addEventListener("popstate",syncDialog);
setLanguage(language);
syncDialog();
